'use strict';
// Background for the Storage screens: the BMW Coding photo (sky and car) from Cluster Redline's settings screen,
// darkened so the readings stay clear, and a small "코딩나눔터 동이/카자미/잼님" + address mark drawn only where a
// page leaves room (see main.js). The car's renderer takes no pixel images, so there the photo is drawn once into
// a cached layer as thin vertical gradient columns; canvases that take pixels get the photo enlarged directly.
const W=480,H=156,DATA='';
// Cafe profile picture (24 x 24 RGB), the same one Cluster Redline shows on its settings screen.
const AW=24,AVATAR='';
let src=null,avatar=null,big=null;
function inflate(b){try{return require('zlib').inflateSync(Buffer.from(b,'base64'));}catch(e){return null;}}
function source(){if(!src)src=inflate(DATA);return src;}
function sample(fx,fy){const s=source();fx=Math.max(0,Math.min(W-1,fx));fy=Math.max(0,Math.min(H-1,fy));const x0=Math.floor(fx),y0=Math.floor(fy),x1=Math.min(W-1,x0+1),y1=Math.min(H-1,y0+1),tx=fx-x0,ty=fy-y0,o=[0,0,0];
 for(let k=0;k<3;k++){const a=s[(y0*W+x0)*3+k],b=s[(y0*W+x1)*3+k],c=s[(y1*W+x0)*3+k],e=s[(y1*W+x1)*3+k];o[k]=Math.round((a*(1-tx)+b*tx)*(1-ty)+(c*(1-tx)+e*tx)*ty);}return o;}
// The photo enlarged to w x h (RGBA), for canvases that take pixels.
function image(w,h){
 if(big&&big.w===w&&big.h===h)return big;if(!source())return null;
 const d=Buffer.alloc(w*h*4);
 for(let y=0;y<h;y++)for(let x=0;x<w;x++){const c=sample((x+0.5)*W/w-0.5,(y+0.5)*H/h-0.5),o=(y*w+x)*4;d[o]=c[0];d[o+1]=c[1];d[o+2]=c[2];d[o+3]=255;}
 big={w,h,d};return big;
}
// The photo as vertical gradient columns (4 px wide, a stop every 10 px).
function columns(cv,w,h){
 if(!source())return;const cw=4,step=10;
 for(let x=0;x<w;x+=cw){const stops=[];for(let y=0;y<=h;y+=step){const c=sample((x+cw/2)*W/w-0.5,y*H/h-0.5);stops.push([Math.min(1,y/h),[c[0],c[1],c[2],255]]);}cv.gradientRect(x,0,Math.min(cw,w-x),h,stops);}
}
// The Korean edition (its locale says ko) shows the Korean watermark. The Store runtime's kit/fonts has no
// has(), so the Korean atlas is checked with get() (which falls back to 'label' when it is missing).
function korean(){try{return require('./kit/i18n').getLanguage()==='ko';}catch(e){return false;}}
const LINK='Http://blog.naver.com/codingbmw';
// The brand mark as on Cluster Redline's settings screen, right-aligned at (right, base):
// Korean edition: profile picture, "서울II잼님 · address" and "BMW Coding 배움터" under it;
// English edition: the address and "BMW Coding" (no Korean name or picture).
const TOP=14,BRAND=23,S=1.5;
function size(cv,ko){
 const top=ko?'서울II잼님  ·  '+LINK:LINK,brand=ko?'BMW Coding 배움터':'BMW Coding';
 const w1=cv.textWidth?cv.textWidth(top,TOP,{literal:true}):top.length*9,w2=cv.textWidth?cv.textWidth(brand,BRAND,{literal:true}):brand.length*14;
 return {top,brand,text:Math.max(w1,w2),w:Math.max(w1,w2)+(ko?12+AW*S:0)};
}
// The picture as S-px gradient columns (two stops per pixel row: hard edges, 48 of the GPU's 64 stops),
// transparent outside the circle; native renderers take only gradients in cached layers.
let faceLayer=null;
function face(){
 if(faceLayer)return faceLayer;if(!avatar)avatar=inflate(AVATAR);if(!avatar)return null;
 faceLayer=require('./kit/record').makeLayer(AW*S,AW*S,(r)=>{
  for(let x=0;x<AW;x++){const stops=[];
   for(let y=0;y<AW;y++){const dx=x-AW/2+0.5,dy=y-AW/2+0.5,o=(y*AW+x)*3,c=dx*dx+dy*dy>(AW/2)*(AW/2)?[0,0,0,0]:[avatar[o],avatar[o+1],avatar[o+2],215];
    stops.push([y/AW+(y?0.001:0),c]);stops.push([(y+1)/AW-(y<AW-1?0.001:0),c]);}
   if(stops.some((st)=>st[1][3]>0))r.gradientRect(x*S,0,S,AW*S,stops);}
 });
 return faceLayer;
}
function watermark(cv,right,base){
 const ko=korean(),a=175,m=size(cv,ko);
 if(ko){const ax=Math.round(right-m.text-12-AW*S),ay=Math.round(base-AW*S+3);
  if(typeof cv.blit==='function'&&typeof cv.drawImage!=='function'){try{const L=face();if(L)cv.blit(L,ax,ay);}catch(e){}}
  else{if(!avatar)avatar=inflate(AVATAR);
   if(avatar)for(let y=0;y<AW;y++)for(let x=0;x<AW;x++){const dx=x-AW/2+0.5,dy=y-AW/2+0.5;if(dx*dx+dy*dy>(AW/2)*(AW/2))continue;const o=(y*AW+x)*3;cv.fillRect(ax+x*S,ay+y*S,S,S,[avatar[o],avatar[o+1],avatar[o+2],215]);}}}
 cv.text(m.top,right,base-26,TOP,[230,236,242,a],{align:'right',literal:true});
 cv.text(m.brand,right,base,BRAND,[255,255,255,a+35],{align:'right',literal:true});
}
// Paint the photo behind everything (after clear, before the menus).
// Paint the photo behind everything (after clear, before the menus), into x0..w, y0..h (the part the screen shows:
// Seats starts it where its menu does, so the HMI's back arrow column does not cut into it). Layers per size.
const layers={};
function paint(cv,w,h,x0,y0){
 x0=Math.max(0,Math.round(x0||0));y0=Math.max(0,Math.round(y0||0));const rw=w-x0,rh=h-y0;if(rw<=0||rh<=0)return false;
 if(typeof cv.drawImage==='function'){const img=image(rw,rh);if(img)cv.drawImage(img.d,rw,rh,x0,y0,rw,rh);return true;}
 if(typeof cv.blit==='function'){
  try{const k=rw+'x'+rh;if(!layers[k])layers[k]=require('./kit/record').makeLayer(rw,rh,r=>columns(r,rw,rh));cv.blit(layers[k],x0,y0);return true;}catch(e){return false;}
 }
 return false;
}
// The mark at (right, base), drawn into the frame; only the picture is a cached (gradient) layer.
function mark(cv,right,base){watermark(cv,right,base);return true;}
module.exports={paint,mark,image};
